#!/usr/bin/env python3
"""Apply committed overlays to a project generated by the exact pinned Flutter SDK."""
from __future__ import annotations
import argparse
import json
from pathlib import Path
import plistlib
import shutil
from run_validation import ROOT, file_sha256, git_value

SOURCE = ROOT / 'experiments/flutter_probe'
SYMBOLS = ['version', 'start', 'poll', 'cancel', 'release']
LAN_SYMBOLS = ['version','prepare','poll','read','push','configure','start','cancel','release']
FFI_SYMBOLS = ['ak_m0_probe_' + s for s in SYMBOLS] + ['ak_m0_lan_' + s for s in LAN_SYMBOLS]


def replace_exact(path: Path, old: str, new: str, count: int = 1) -> None:
    text = path.read_text(encoding='utf-8')
    if text.count(old) != count:
        raise ValueError(f'Pinned template mismatch: {path.name}')
    path.write_text(text.replace(old, new), encoding='utf-8', newline='\n')


def update_plist(path: Path, additions: dict) -> None:
    data = plistlib.loads(path.read_bytes())
    data.update(additions)
    path.write_bytes(plistlib.dumps(data, sort_keys=False))


def prepare(project: Path, native: Path, platform: str) -> None:
    if not (project / '.metadata').is_file() or not native.is_file():
        raise ValueError('Generated project or native library missing')
    for name in ['lib', 'test', 'tool']:
        shutil.copytree(SOURCE / name, project / name, dirs_exist_ok=True)
    for name in ['pubspec.yaml', 'pubspec.lock', 'analysis_options.yaml']:
        shutil.copy2(SOURCE / name, project / name)
    if platform in ['linux', 'windows']:
        # CMake quotes a known local build path; never an untrusted user input.
        destination = '${INSTALL_BUNDLE_LIB_DIR}'
        with (project / platform / 'CMakeLists.txt').open('a', encoding='utf-8') as stream:
            stream.write(f'\ninstall(FILES "{native.as_posix()}" DESTINATION "{destination}" COMPONENT Runtime)\n')
    if platform == 'android':
        build = project / 'android/app/build.gradle.kts'
        for old, new in [
            ('compileSdk = flutter.compileSdkVersion', 'compileSdk = 37\n    buildToolsVersion = "36.0.0"'),
            ('ndkVersion = flutter.ndkVersion', 'ndkVersion = "29.0.14206865"'),
            ('minSdk = flutter.minSdkVersion', 'minSdk = 26'),
            ('targetSdk = flutter.targetSdkVersion', 'targetSdk = 37'),
            ('    buildTypes {', '    packaging { jniLibs.keepDebugSymbols += setOf("**/libak_m0_probe.so") }\n    buildTypes {'),
        ]: replace_exact(build, old, new)
        # Minimal compatible patch for API37, retaining the SDK template's Gradle/Kotlin.
        replace_exact(project / 'android/settings.gradle.kts',
                      'version "9.1.0"', 'version "9.1.1"')
        manifest = project / 'android/app/src/main/AndroidManifest.xml'
        replace_exact(manifest, '    <application',
            '    <uses-permission android:name="android.permission.INTERNET"/>\n'
            '    <uses-permission android:name="android.permission.ACCESS_LOCAL_NETWORK"/>\n'
            '    <application')
        activity = project / 'android/app/src/main/kotlin/dev/ak/ak_m0_probe/MainActivity.kt'
        shutil.copy2(SOURCE / 'platform/MainActivity.kt', activity)
        jni = project / 'android/app/src/main/jniLibs/arm64-v8a'
        jni.mkdir(parents=True, exist_ok=True)
        shutil.copy2(native, jni / 'libak_m0_probe.so')
    if platform in ['ios', 'macos']:
        config = project / ('ios/Flutter/Release.xcconfig' if platform == 'ios'
                            else 'macos/Runner/Configs/Release.xcconfig')
        flags = ' '.join(f'-Wl,-u,_{symbol}' for symbol in FFI_SYMBOLS)
        with config.open('a', encoding='utf-8') as stream:
            stream.write(f'\nOTHER_LDFLAGS = $(inherited) -force_load "{native.as_posix()}" '
                         f'-framework Security -framework SystemConfiguration -lresolv -liconv {flags} -Wl,-export_dynamic\n'
                         'DEAD_CODE_STRIPPING = NO\nSTRIP_STYLE = non-global\n')
        if platform == 'ios':
            (project / 'ios/Runner/AppDelegate.swift').write_text(
                (SOURCE / 'platform/AppDelegate.swift').read_text(encoding='utf-8') + '\n' +
                (SOURCE / 'platform/DirectoryOperation.swift').read_text(encoding='utf-8'), encoding='utf-8')
            update_plist(project / 'ios/Runner/Info.plist', {
                'NSLocalNetworkUsageDescription': '仅用于用户主动启动的本地连接实验。拒绝不会绕过权限。'})
        else:
            # M0's declared macOS ABI is arm64, not a universal x86_64 promise.
            with config.open('a', encoding='utf-8') as stream:
                stream.write('ARCHS = arm64\nEXCLUDED_ARCHS = x86_64\n')
            pbx = project / 'macos/Runner.xcodeproj/project.pbxproj'
            replace_exact(pbx, 'MACOSX_DEPLOYMENT_TARGET = 12.0;',
                          'MACOSX_DEPLOYMENT_TARGET = 13.0;', 3)
            update_plist(project / 'macos/Runner/Info.plist', {
                'NSLocalNetworkUsageDescription': '仅在用户核对身份并确认后执行双设备局域网合成数据实验。'})
            update_plist(project / 'macos/Runner/Release.entitlements', {
                'com.apple.security.network.client': True,
                'com.apple.security.network.server': True})
    files = {str(p.relative_to(project)): file_sha256(p) for p in sorted(project.rglob('*'))
             if p.is_file() and not any(part in ['.git', 'build', '.dart_tool'] for part in p.relative_to(project).parts)}
    report = {'source_commit': git_value('rev-parse', 'HEAD'), 'platform': platform,
              'generation': 'exact Flutter SDK scaffold plus committed overlays; generated files are not committed source',
              'files': files, 'native_sha256': file_sha256(native)}
    (project / 'GENERATED_PROVENANCE.json').write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')


if __name__ == '__main__':
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--project', type=Path, required=True)
    parser.add_argument('--native', type=Path, required=True)
    parser.add_argument('--platform', choices=['linux', 'windows', 'macos', 'android', 'ios'], required=True)
    args = parser.parse_args()
    prepare(args.project.resolve(), args.native.resolve(), args.platform)
